-- LPGR'APP — catalogue initial (33 titres). Réexécutable; n'initialise PAS les stocks réels.
-- Les stocks historiques Excel restent des références; réaliser un inventaire physique d'ouverture.
begin;
on conflict (tome_number) do update set
 title=excluded.title,status=excluded.status,price_public=excluded.price_public,price_reduced=excluded.price_reduced,reorder_threshold=excluded.reorder_threshold,critical_threshold=excluded.critical_threshold,legacy_initial_stock=excluded.legacy_initial_stock,legacy_stock_note=excluded.legacy_stock_note,illustrator_cost=excluded.illustrator_cost,printer_cost=excluded.printer_cost,isbn=excluded.isbn,ean=excluded.ean,publication_date=excluded.publication_date,legal_deposit_date=excluded.legal_deposit_date,youth_commission_date=excluded.youth_commission_date,publisher=excluded.publisher,vat_rate=excluded.vat_rate,notes=excluded.notes,updated_at=now();
commit;

-- Contrôle attendu : 33 lignes, tomes 1 à 33.
select count(*) as nombre_de_titres, min(tome_number) as premier_tome, max(tome_number) as dernier_tome from public.books;